#include <iostream>
using namespace std;
struct A { A() { cout << "A "; } ~A() { cout << "~A "; } };
struct B { B() { cout << "B "; } ~B() { cout << "~B "; } };
struct M { M() { cout << "M "; } ~M() { cout << "~M "; } };
struct C : B, A {
    M m;
    C() : A(), B() { cout << "C\n"; }
    ~C() { cout << "~C "; }
};
int main() {
    C obj;
    return 0;
}

#include <iostream>
using namespace std;
struct A { int id; A(int x) : id(x) { cout << "A(" << x << ") "; } };
struct B : virtual A { B() : A(1) { cout << "B "; } };
struct C : virtual A { C() : A(2) { cout << "C "; } };
struct D : B, C { D() : A(9) { cout << "D "; } };
int main() {
    D d;
    B b;
    cout << "\n" << d.id << " " << b.id << "\n";
    return 0;
}

